import{_ as e,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Catalog Attribute Families — Datagrid Listing","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-families-list","title":"List Attribute Families (Datagrid)","description":"Paginated, filterable, sortable attribute family list mirroring the Bagisto admin Catalog → Attribute Families datagrid. Returns the standard `{ data, meta }` envelope. Only 3 columns are returned — id, code, name — because the underlying table carries no timestamps.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/families?per_page=10&page=1&sort=id&order=desc\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"per_page=10&page=1&sort=id&order=desc\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"default\\",\\n      \\"name\\": \\"Default\\"\\n    },\\n    {\\n      \\"id\\": 3,\\n      \\"code\\": \\"apparel\\",\\n      \\"name\\": \\"Apparel\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 2,\\n    \\"from\\": 1,\\n    \\"to\\": 2\\n  }\\n}\\n","commonErrors":[{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/families/families-listing.md","filePath":"api/rest-api/admin/catalog/families/families-listing.md","lastUpdated":1787725411000}'),r={name:"api/rest-api/admin/catalog/families/families-listing.md"};function i(n,t,s,l,c,m){return d(),a("div",null,t[0]||(t[0]=[o('<h1 id="catalog-attribute-families-—-datagrid-listing" tabindex="-1">Catalog Attribute Families — Datagrid Listing <a class="header-anchor" href="#catalog-attribute-families-—-datagrid-listing" aria-label="Permalink to &quot;Catalog Attribute Families — Datagrid Listing&quot;">​</a></h1><p>Paginated, filterable, and sortable attribute family list that mirrors the Bagisto admin <strong>Catalog → Attribute Families</strong> datagrid 1:1. This is the authoritative family-management listing for the admin API — same 3 columns and the same sort options used by the datagrid.</p><p>For how a family&#39;s attribute groups and attributes are structured, and the delete guards, see the <a href="/api/rest-api/admin/catalog/families/">Attribute Families overview</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/families</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>Page number (1-based, default <code>1</code>)</td><td><code>1</code></td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>id</code></td><td>string</td><td>Filter by family ID — single integer or comma-separated list (e.g. <code>&quot;1&quot;</code> or <code>&quot;1,2&quot;</code>)</td><td><code>1</code></td></tr><tr><td><code>code</code></td><td>string</td><td>Partial family code match (SQL <code>LIKE %value%</code>)</td><td><code>default</code></td></tr><tr><td><code>name</code></td><td>string</td><td>Partial family name match (SQL <code>LIKE %value%</code>)</td><td><code>Default</code></td></tr><tr><td><code>sort</code></td><td>string</td><td>Column to sort by (see Sorting section below)</td><td><code>id</code></td></tr><tr><td><code>order</code></td><td>string</td><td>Sort direction: <code>asc</code> or <code>desc</code> (default <code>desc</code>)</td><td><code>desc</code></td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>Responses use the standard admin <code>{ data, meta }</code> envelope.</p><h3 id="meta-object" tabindex="-1"><code>meta</code> object <a class="header-anchor" href="#meta-object" aria-label="Permalink to &quot;`meta` object&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>currentPage</code></td><td>integer</td><td>Current page number (1-based)</td></tr><tr><td><code>perPage</code></td><td>integer</td><td>Number of items on this page</td></tr><tr><td><code>lastPage</code></td><td>integer</td><td>Total number of pages</td></tr><tr><td><code>total</code></td><td>integer</td><td>Total matching families</td></tr><tr><td><code>from</code></td><td>integer</td><td>1-based index of the first item on this page</td></tr><tr><td><code>to</code></td><td>integer</td><td>1-based index of the last item on this page</td></tr></tbody></table><h3 id="row-fields-data" tabindex="-1">Row fields (<code>data[]</code>) <a class="header-anchor" href="#row-fields-data" aria-label="Permalink to &quot;Row fields (`data[]`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute family ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Family code (e.g. <code>default</code>, <code>apparel</code>)</td></tr><tr><td><code>name</code></td><td>string</td><td>Family display name (e.g. <code>Default</code>, <code>Apparel</code>)</td></tr></tbody></table><p>The listing is deliberately three columns. Families carry <strong>no timestamps at all</strong> — there is no <code>createdAt</code> or <code>updatedAt</code> on this resource, unlike every other admin listing — so you cannot sort or filter by date here. Attribute groups and their attributes resolve only on <a href="/api/rest-api/admin/catalog/families/families-detail.html"><code>GET /api/admin/catalog/families/{id}</code></a>.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter form</th><th>Example</th></tr></thead><tbody><tr><td>Separate <code>sort</code> + <code>order</code> params</td><td><code>?sort=id&amp;order=desc</code></td></tr></tbody></table><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Family ID (default)</td></tr><tr><td><code>code</code></td><td>Family code</td></tr><tr><td><code>name</code></td><td>Family display name</td></tr></tbody></table><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><ul><li>Default page size: <strong>10</strong> items</li><li>Maximum page size: <strong>50</strong> items</li><li>Use <code>?page=N</code> for page navigation and <code>?per_page=N</code> to control page size</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Cause</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>Missing, expired, or revoked admin Bearer token</td></tr><tr><td><code>401 Unauthorized</code></td><td>Missing or invalid admin Bearer token</td></tr></tbody></table><p><strong>Unknown filter parameters</strong> are silently ignored — no error is returned.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Only 3 columns are returned.</strong> The listing mirrors the admin datagrid exactly: <code>id</code>, <code>code</code>, <code>name</code>. No timestamps exist on the <code>attribute_families</code> table. No attribute-group or attribute data is included — use <code>GET /api/admin/catalog/families/{id}</code> for the full nested payload.</li><li><strong>No automatic filter applied.</strong> All families (system and user-defined) are returned by default. There is no <code>is_user_defined</code> filter on families — all families are returned.</li><li>Envelope-wrapped: <code>{ data: [...], meta: { currentPage, perPage, lastPage, total, from, to } }</code>.</li><li><code>per_page</code> caps at <strong>50</strong>; values ≤ 0 fall back to the default of <strong>10</strong>.</li></ul>',25)]))}const p=e(r,[["render",i]]);export{g as __pageData,p as default};
